    internal static partial int obrain_remove_edge_property(nint db, ulong id, string key);

    /// <summary>Free an edge returned by obrain_get_edge.</summary>
    [LibraryImport(LibName)]
    internal static partial void obrain_free_edge(nint edge);

    /// <summary>Edge ID.</summary>
    [LibraryImport(LibName)]
    internal static partial ulong obrain_edge_id(nint edge);

    /// <summary>Source node ID.</summary>
    [LibraryImport(LibName)]
    internal static partial ulong obrain_edge_source_id(nint edge);

    /// <summary>Target node ID.</summary>
    [LibraryImport(LibName)]
    internal static partial ulong obrain_edge_target_id(nint edge);

    /// <summary>Edge type string. Valid until obrain_free_edge.</summary>
    [LibraryImport(LibName)]
    internal static partial nint obrain_edge_type(nint edge);

    /// <summary>Edge properties JSON. Valid until obrain_free_edge.</summary>
    [LibraryImport(LibName)]
    internal static partial nint obrain_edge_properties_json(nint edge);

    // =========================================================================
    // Indexes
    // =========================================================================

    /// <summary>Create a property index (the header keys it on the property only). Returns status.</summary>
    [LibraryImport(LibName, StringMarshalling = StringMarshalling.Utf8)]
    internal static partial int obrain_create_property_index(nint db, string property);

    /// <summary>Drop a property index. Returns 1 if dropped, 0 if not found, -1 on error.</summary>
    [LibraryImport(LibName, StringMarshalling = StringMarshalling.Utf8)]
    internal static partial int obrain_drop_property_index(nint db, string property);

    /// <summary>Check if a property index exists. Returns 1 if exists, 0 otherwise.</summary>
